end

function UIFishPoolCreelBatchItemNode:__delete()
    self._fishDojo = nil
    self._cb = nil
    self._curType = nil
    self._curNum = 0
    self._maxNum = 0
end

function UIFishPoolCreelBatchItemNode:Awake()    
    SetButtonAction(self.BtnAdd, Bind(self, self.OnBtnAdd))
    SetButtonAction(self.BtnReduce, Bind(self, self.OnBtnDel))
    self.InputFieldNumber.onValueChanged:AddListener(function(num)
        num = checkNumber(num)
        if num <= 0 then
            self._curNum = 0
        elseif num >= self._maxNum then
            self._curNum = self._maxNum
        else
            self._curNum = num    
        end
        self:RefreshSelectNum()
    end)
end

