--增加
function UIFishPoolCreelBatchItemNode:OnBtnAdd()
    if checkNumber(self._curNum) >= checkNumber(self._maxNum) then
        return
    end
    self._curNum = checkNumber(self._curNum) + 1
    self:RefreshSelectNum()
end

--减少
function UIFishPoolCreelBatchItemNode:OnBtnDel()
    if checkNumber(self._curNum) <= 1 then
        return
    end
    self._curNum = checkNumber(self._curNum) - 1
    self:RefreshSelectNum()
end

function UIFishPoolCreelBatchItemNode:RefreshSelectNum()
    self.InputFieldNumber.text = self._curNum

    local vo = FishingUtils.GetFishingSpeciesVo(self._fishDojo.fishId)

    if self._curType == ConstantsFishing.FishBasketType.Make then
        local num = math.floor(math.floor(checkNumber(vo.baitNum)) * self._curNum)
        CfUtils.FillText(self.TextNumber, "X"..num)
    elseif self._curType == ConstantsFishing.FishBasketType.Sell then
        local ratingVo = FishingUtils.GetFishingRatingVo(self._fishDojo.rating)
        local num = math.floor(vo.price * (1 + ratingVo.priceAddition)) * self._curNum
        CfUtils.FillText(self.TextNumber, "X"..num)
    end

    if self._cb then
        self._cb(self._curNum)
    end
end

function UIFishPoolCreelBatchItemNode:Refresh(data, type, cb)
    if not data then
        return
    end

    if not self._goodNodeScr then 
        self._goodNodeScr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    end
    self._fishDojo = FishingUtils.GetFishingFishDojo(data.fishId, data.rating)
    if not self._fishDojo then
        return
    end
    self._maxNum = checkNumber(self._fishDojo.num)

    self._cb = cb
    self._curType = checkNumber(type)

    self:FillSelf()

    self._curNum =  self._maxNum
    self:RefreshSelectNum()
end

function UIFishPoolCreelBatchItemNode:FillSelf()
    self:RefreshSelectActive(false)
    CfUtils.RefeshGoodGo(self.GoodNode, self._fishDojo.fishId, self._fishDojo.num, 0.5, nil, function()

    end)

    KTool.SetActive(self.StatusBait, self._curType == ConstantsFishing.FishBasketType.Make)
    KTool.SetActive(self.StatusSell, self._curType == ConstantsFishing.FishBasketType.Sell)

    if self._curType == ConstantsFishing.FishBasketType.Make then
        self:FillMakeInfo()
    elseif self._curType == ConstantsFishing.FishBasketType.Sell then
        self:FillSellInfo()
    end
end

function UIFishPoolCreelBatchItemNode:FillMakeInfo()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._fishDojo.fishId)
    if vo then
        CfUtils.FillText(self.TextName, vo.name)
    end

    vo = FishingUtils.GetFishingSpeciesVo(self._fishDojo.fishId)
    if vo then
        local path = GoodsConfMgr:GetInstance():GetPhotoPathById(vo.baitMaking)
        CfUtils.FillImage(self.ImgBaitIcon, path)

        --local num = math.floor(math.floor(checkNumber(vo.baitNum)) * self._fishDojo.num)
        --CfUtils.FillText(self.TextNumber, "X"..num)

        local isCanBait = checkNumber(vo.baitMaking) > 0
        local isCanGetSpecialBait = checkNumber(vo.specialBait) > 0 

        KTool.SetActive(self.BtnBaitIcon, isCanBait)
        if isCanBait then
            local baitVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.baitMaking)
            if baitVo then
                CfUtils.FillImage(self.BtnBaitIcon.transform:Find("ImgBaitIcon"), baitVo.photoPath)
                SetButtonAction(self.BtnBaitIcon, function()
                    GameUtils.ShowCommonGoodsTipsBoard(self.BtnBaitIcon, vo.baitMaking, false)
                end)
            end
        else
            SetButtonAction(self.BtnIconLeft, function()
                
            end)
        end

        KTool.SetActive(self.BtnBaitIcon2, isCanGetSpecialBait)
        if isCanGetSpecialBait then
            local baitVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.specialBait)
            if baitVo then
                CfUtils.FillImage(self.BtnBaitIcon2.transform:Find("ImgIcon"), baitVo.photoPath)
                SetButtonAction(self.BtnBaitIcon2, function()
                    GameUtils.ShowCommonGoodsTipsBoard(self.BtnBaitIcon2, vo.specialBait, false)
                end)
            end
        else
            SetButtonAction(self.BtnBaitIcon2, function()
                
            end)
        end
    end
end

